fn wait_first_frame(socket: std::os::fd::RawFd, end: Instant) -> Result<(), AgentdError> {
    let remaining = end.checked_duration_since(Instant::now())
        .filter(|value| !value.is_zero() && *value <= Duration::from_secs(30))
        .ok_or_else(|| protocol("the common Source startup window expired"))?;
    let timeout = i32::try_from(remaining.as_millis().max(1)).map_err(protocol)?;
    let mut descriptor = libc::pollfd { fd: socket, events: libc::POLLIN, revents: 0 };
    // SAFETY: the live original channel owns socket for this call. The single
    // initialized pollfd is valid, and poll neither consumes nor duplicates it.
    let ready = unsafe { libc::poll(&mut descriptor, 1, timeout) };
    if ready != 1 || descriptor.revents & (libc::POLLERR | libc::POLLHUP | libc::POLLNVAL) != 0
        || descriptor.revents & libc::POLLIN == 0
    { return Err(protocol("no original Source first frame within the common startup window")); }
    wire::before(end).map_err(protocol)
}

